```tsx
import { useId } from "react";
import "./EmptyState.css";

export interface EmptyStateProps {
  title: string;
  message: string;
  actionLabel: string;
  onAction: () => void;
}

export function EmptyState({ title, message, actionLabel, onAction }: EmptyStateProps) {
  const titleId = useId();

  return (
    <section className="empty-state" aria-labelledby={titleId}>
      <h2 id={titleId} className="empty-state__title">
        {title}
      </h2>
      <p className="empty-state__message">{message}</p>
      <button type="button" className="empty-state__action" onClick={onAction}>
        {actionLabel}
      </button>
    </section>
  );
}
```

```css
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  max-width: 28rem;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3rem) clamp(1rem, 3vw, 2rem);
  border: 1px dashed var(--axon-ahead);
  border-radius: 1rem;
  text-align: center;
  color: var(--ink);
}

.empty-state__title {
  margin: 0;
  font-size: clamp(1.25rem, 1.1rem + 0.8vw, 1.75rem);
  font-weight: 600;
  line-height: 1.25;
}

.empty-state__message {
  margin: 0;
  font-size: clamp(0.9375rem, 0.9rem + 0.2vw, 1.0625rem);
  line-height: 1.5;
  color: var(--muted);
}

.empty-state__action {
  font: inherit;
  font-size: clamp(0.9375rem, 0.9rem + 0.2vw, 1.0625rem);
  font-weight: 600;
  margin-top: 0.5rem;
  padding: 0.625rem 1.5rem;
  border: 1px solid var(--myelin);
  border-radius: 999px;
  background: var(--myelin);
  color: var(--slide);
  cursor: pointer;
  transition: box-shadow 150ms ease, border-color 150ms ease;
}

.empty-state__action:hover {
  box-shadow: 0 0 0 4px var(--myelin-wash);
}

.empty-state__action:focus-visible {
  border-color: var(--cresyl);
}

@media (prefers-reduced-motion: reduce) {
  .empty-state__action {
    transition: none;
  }
}

:root[data-motion="reduce"] .empty-state__action {
  transition: none;
}
```

